import{_ as a,c as t,o as i,a0 as r}from"./chunks/framework.CAoHpFZS.js";const O=JSON.parse('{"title":"RDB快照和AOF追加","description":"","frontmatter":{},"headers":[],"relativePath":"article/redis/RDB快照和AOF追加.md","filePath":"article/redis/RDB快照和AOF追加.md"}'),s={name:"article/redis/RDB快照和AOF追加.md"};function l(o,e,p,d,n,R){return i(),t("div",null,e[0]||(e[0]=[r('<h1 id="rdb快照和aof追加" tabindex="-1">RDB快照和AOF追加 <a class="header-anchor" href="#rdb快照和aof追加" aria-label="Permalink to &quot;RDB快照和AOF追加&quot;">​</a></h1><p>两种机制的本质：</p><ol><li>RDB 快照（Redis Database）</li></ol><p>RDB 是 Redis 在指定时间间隔内，将内存中的全量数据以二进制形式快照到磁盘的 .rdb 文件中（比如每 5 分钟生成一次快照）。</p><p>核心特点： 是全量备份，文件体积小、恢复速度快； 缺点是如果快照间隔内 Redis 崩溃，这段时间的新数据会丢失（比如 5 分钟快照一次，崩溃时最后 3 分钟的数据没保存就没了）； 生成快照时 Redis 会 fork 子进程处理，对主进程影响小。</p><ol start="2"><li>AOF 追加文件（Append Only File）</li></ol><p>AOF 是将 Redis 执行过的所有写命令（比如 SET key value、HSET hash field val）以文本形式追加到 .aof 文件中，Redis 重启时会重新执行这些命令来恢复数据。</p><p>核心特点： 是增量记录，默认配置下每秒刷盘一次（或每次写命令都刷盘），数据丢失风险极低（最多丢 1 秒数据）； 缺点是文件体积会随时间变大（比如反复修改同一个 key 会记录多条命令），恢复速度比 RDB 慢； 支持自动重写（AOF rewrite），会合并冗余命令，减小文件体积（比如把 SET a 1、SET a 2 合并成 SET a 2）。</p><ol start="3"><li>RDB + AOF 组合使用</li></ol><p>Redis 4.0 及以上版本支持同时启用两种持久化机制</p><p>核心逻辑是：</p><p>正常运行时： RDB 按配置的时间策略（如 save 900 1：900 秒内至少 1 个写操作就生成快照）生成全量快照； AOF 实时追加所有写命令，保证数据的实时性。</p><p>Redis 重启恢复时： 优先加载 AOF 文件（因为 AOF 数据更完整），只有 AOF 文件不存在时才加载 RDB 文件。</p>',13)]))}const A=a(s,[["render",l]]);export{O as __pageData,A as default};
